const root=process.cwd();
const full=file=>path.join(root,file);
const read=file=>fs.readFileSync(full(file),'utf8');
const write=(file,content)=>{fs.mkdirSync(path.dirname(full(file)),{recursive:true});fs.writeFileSync(full(file),content)};
function replaceOnce(file,oldText,newText){const src=read(file);const count=src.split(oldText).length-1;if(count!==1)throw new Error(`v0.5.5 guard ${file}: expected 1 exact match, found ${count}`);write(file,src.replace(oldText,newText));}
function replaceRegex(file,regex,replacement){const src=read(file);const matches=[...src.matchAll(new RegExp(regex.source,regex.flags.includes('g')?regex.flags:regex.flags+'g'))];if(matches.length!==1)throw new Error(`v0.5.5 regex guard ${file}: expected 1 match, found ${matches.length}`);write(file,src.replace(regex,replacement));}

